package dev.gigaherz.toolbelt;

import dev.gigaherz.toolbelt.belt.ToolBeltItem;
import net.minecraft.core.NonNullList;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.IItemHandler;

import java.util.Optional;
import java.util.function.IntFunction;

public abstract class BeltFinder
{
    private static NonNullList<BeltFinder> instances = NonNullList.create();

    public static synchronized void addFinder(BeltFinder finder)
    {
        instances.add(0, finder);
    }

    public static synchronized boolean isFinderRegistered(String name)
    {
        return instances.stream().anyMatch(f -> f.getName().equals(name));
    }

    public static Optional<? extends BeltGetter> findBelt(LivingEntity player)
    {
        return findBelt(player, false);
    }

    public static Optional<? extends BeltGetter> findBelt(LivingEntity player, boolean allowCosmetic)
    {
        return instances.stream()
                .map(f -> f.findStack(player, allowCosmetic))
                .filter(Optional::isPresent)
                .findFirst()
                .orElseGet(Optional::empty);
    }

    public static void sendSync(Player player)
    {
        findBelt(player).ifPresent(BeltGetter::syncToClients);
    }

    public static void setBeltFromPacket(Player player, String where, int slot, ItemStack stack)
    {
        for (BeltFinder finder : instances)
        {
            if (finder.getName().equals(where))
            {
                finder.getSlotFromId(player, slot).ifPresent(getter -> getter.setBelt(stack));
            }
        }
    }

    public abstract String getName();

    public abstract Optional<? extends BeltGetter> findStack(LivingEntity player, boolean allowCosmetic);

    protected Optional<BeltGetter> getSlotFromId(Player player, int slotId)
    {
        return Optional.empty();
    }

    protected final Optional<? extends BeltGetter> findBeltInInventory(IItemHandler inventory, IntFunction<? extends BeltGetter> getterFactory)
    {
        for (int i = 0; i < inventory.getSlots(); i++)
        {
            ItemStack inSlot = inventory.getStackInSlot(i);
            if (inSlot.getCount() > 0)
            {
                if (inSlot.getItem() instanceof ToolBeltItem)
                {
                    return Optional.of(getterFactory.apply(i));
                }
            }
        }
        return Optional.empty();
    }

    public interface BeltGetter
    {
        ItemStack getBelt();

        default void setBelt(ItemStack stack)
        {
            // Defaults to "do nothing"
        }

        default boolean isHidden()
        {
            return false;
        }

        void syncToClients();
    }
}

package dev.gigaherz.toolbelt;

import dev.gigaherz.toolbelt.belt.ToolBeltItem;
import dev.gigaherz.toolbelt.customslots.IExtensionSlot;
import dev.gigaherz.toolbelt.network.BeltContentsChange;
import dev.gigaherz.toolbelt.slot.BeltExtensionSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityManager;
import net.minecraftforge.common.capabilities.CapabilityToken;
import net.minecraftforge.network.PacketDistributor;

import java.util.Optional;

public class BeltFinderBeltSlot extends BeltFinder
{
    public static final String FINDER_ID = "belt_slot";

    public static Capability<BeltExtensionSlot> BELT_EXTENSION_SLOT_CAPABILITY
            = CapabilityManager.get(new CapabilityToken<>()
    {
    });

    public static void initBaubles()
    {
        BeltFinder.addFinder(new BeltFinderBeltSlot());
    }

    @Override
    protected Optional<BeltGetter> getSlotFromId(Player player, int slotId)
    {
        return BeltExtensionSlot.get(player)
                .resolve()
                .map(BeltExtensionSlot::getSlots)
                .map(slots -> slots.get(slotId))
                .map(slot -> new ExtensionSlotBeltGetter(player, slot));
    }

    @Override
    public String getName()
    {
        return FINDER_ID;
    }

    @Override
    public Optional<? extends BeltGetter> findStack(LivingEntity player, boolean allowCosmetic)
    {
        return BeltExtensionSlot.get(player)
                .resolve()
                .flatMap(ext -> ext.getSlots().stream()
                        .filter(slot -> slot.getContents().getItem() instanceof ToolBeltItem)
                        .map(slot -> new ExtensionSlotBeltGetter(player, slot))
                        .findFirst());
    }

    private static class ExtensionSlotBeltGetter implements BeltGetter
    {
        private final LivingEntity player;
        private final IExtensionSlot slot;

        private ExtensionSlotBeltGetter(LivingEntity player, IExtensionSlot slot)
        {
            this.player = player;
            this.slot = slot;
        }

        @Override
        public ItemStack getBelt()
        {
            return slot.getContents();
        }

        @Override
        public void setBelt(ItemStack stack)
        {
            slot.setContents(stack);
        }

        @Override
        public boolean isHidden()
        {
            return false;
        }

        @Override
        public void syncToClients()
        {
            LivingEntity thePlayer = slot.getContainer().getOwner();
            if (thePlayer.level().isClientSide)
                return;
            BeltContentsChange message = new BeltContentsChange(thePlayer, FINDER_ID, 0, slot.getContents());
            ToolBelt.channel.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> thePlayer), message);
        }
    }
}

