public class BeltContainer extends AbstractContainerMenu
{
    public final int beltSlots;
    private ItemStack blockedStack;
    private final int blockedSlot;

    public BeltContainer(int id, Inventory inventory, FriendlyByteBuf extraData)
    {
        this(id, inventory, extraData.readVarInt(), extraData.readItem());
    }

    public BeltContainer(int id, Inventory playerInventory, int blockedSlot, ItemStack blockedStack)
    {
        super(ToolBelt.BELT_MENU.get(), id);
        this.blockedStack = blockedStack;
        this.blockedSlot = blockedSlot;
        if (blockedSlot >= 0 && !stillValid(playerInventory.player))
        {
            blockedStack = ItemStack.EMPTY;
        }
        ToolBeltInventory beltInventory = stillValid(playerInventory.player) && blockedStack.getCapability(ForgeCapabilities.ITEM_HANDLER)
                .orElseThrow(() -> new RuntimeException("Item handler not present.")) instanceof ToolBeltInventory inv
                ? inv : new ToolBeltInventory(new ItemStack(ToolBelt.BELT.get()));

        beltSlots = beltInventory.getSlots();
        int xoff = ((9 - beltSlots) * 18) / 2;
        for (int k = 0; k < beltSlots; ++k)
        {
            this.addSlot(new BeltSlot(playerInventory, blockedStack, blockedSlot, k, 8 + xoff + k * 18, 20));
        }

        bindPlayerInventory(playerInventory);
    }

    private void bindPlayerInventory(Container playerInventory)
    {
        for (int l = 0; l < 3; ++l)
        {
            for (int j1 = 0; j1 < 9; ++j1)
            {
                int index = j1 + l * 9 + 9;
                this.addSlot(
                        blockedSlot == index
                                ? new LockedSlot(playerInventory, index, 8 + j1 * 18, l * 18 + 51)
                                : new Slot(playerInventory, index, 8 + j1 * 18, l * 18 + 51)
                );
            }
        }

        for (int i1 = 0; i1 < 9; ++i1)
        {
            this.addSlot(
                    blockedSlot == i1
                            ? new LockedSlot(playerInventory, i1, 8 + i1 * 18, 109)
                            : new Slot(playerInventory, i1, 8 + i1 * 18, 109)
            );
        }
    }

    @Override
    public void removed(Player playerIn)
    {
        super.removed(playerIn);
        if (!playerIn.level().isClientSide)
            BeltFinder.sendSync(playerIn);
    }

    @Override
    public void broadcastChanges()
    {
        super.broadcastChanges();
    }

    @Override
    public boolean stillValid(Player playerIn)
    {
        ItemStack held = playerIn.getInventory().getItem(blockedSlot);
        var equal = blockedSlot < 0 || held == blockedStack || held.equals(blockedStack, false);
        blockedStack = held;
        return equal;
    }

    @Override
    public void clicked(int slot, int button, ClickType clickType, Player player)
    {
        if (clickType == ClickType.SWAP && button == blockedSlot)
            return;
        super.clicked(slot, button, clickType, player);
    }

    @Override
    public ItemStack quickMoveStack(Player playerIn, int index)
    {
        Slot slot = this.slots.get(index);

        if (slot == null || !slot.hasItem() || index == blockedSlot)
            return ItemStack.EMPTY;

        ItemStack containedStack = slot.getItem();
        ItemStack originalStack = containedStack.copy();

        int start;
        int end;
        boolean reverse = false;
        if (index < beltSlots)
        {
            start = beltSlots;
            end = this.slots.size();
            reverse = true;
        }
        else
        {
            start = 0;
            end = beltSlots;
        }

        if (!this.moveItemStackTo(containedStack, start, end, reverse))
        {
            return ItemStack.EMPTY;
        }

        if (containedStack.getCount() == 0)
        {
            slot.set(ItemStack.EMPTY);
        }
        else
        {
            slot.setChanged();
        }

        return originalStack;
    }
}

package dev.gigaherz.toolbelt.common;

import dev.gigaherz.toolbelt.ConfigData;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.items.IItemHandlerModifiable;
import net.minecraftforge.items.ItemStackHandler;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class BeltSlot extends Slot
{
    private static final Logger LOGGER = LogManager.getLogger();

    public BeltSlot(Container playerInventory, ItemStack heldItem, int blockedSlot, int index, int xPosition, int yPosition)
    {
        super(new Container()
        {
            final Container sourceInventory = playerInventory;
            final int slot = blockedSlot;
            final int subSlot = index;
            final ItemStack fallbackItem = heldItem;

            ItemStack beltStack = null;
            IItemHandlerModifiable inventory = null;

            IItemHandlerModifiable findStack()
            {
                ItemStack stack = slot >= 0 ? sourceInventory.getItem(slot) : fallbackItem;
                if (stack != beltStack)
                {
                    beltStack = stack;
                    inventory = (IItemHandlerModifiable) (
                            stack.getCapability(ForgeCapabilities.ITEM_HANDLER, null)
                                    .orElseGet(() -> {
                                        LOGGER.error("No Inventory!!");
                                        return new ItemStackHandler(9);
                                    })
                    );
                }
                return inventory;
            }

            @Override
            public int getContainerSize()
            {
                return 1;
            }

            @Override
            public boolean isEmpty()
            {
                return getItem(0).getCount() <= 0;
            }

            @Override
            public ItemStack getItem(int n)
            {
                return findStack().getStackInSlot(subSlot);
            }

            @Override
            public ItemStack removeItem(int n, int count)
            {
                return findStack().extractItem(subSlot, count, false);
            }

            @Override
            public ItemStack removeItemNoUpdate(int n)
            {
                ItemStack existing = getItem(0);
                setItem(n, ItemStack.EMPTY);
                return existing;
            }

            @Override
            public void setItem(int n, ItemStack stack)
            {
                findStack().setStackInSlot(subSlot, stack);
            }

            @Override
            public int getMaxStackSize()
            {
                return findStack().getSlotLimit(subSlot);
            }

            @Override
            public void setChanged()
            {

            }

            @Override
            public boolean stillValid(Player player)
            {
                return false;
            }

            @Override
            public void startOpen(Player player)
            {

            }

            @Override
            public void stopOpen(Player player)
            {

            }

            @Override
            public boolean canPlaceItem(int index, ItemStack stack)
            {
                return ConfigData.isItemStackAllowed(stack);
            }

            @Override
            public void clearContent()
            {

            }
        }, blockedSlot, xPosition, yPosition);
    }

    @Override
    public boolean mayPlace(ItemStack stack)
    {
        return ConfigData.isItemStackAllowed(stack);
    }
}

package dev.gigaherz.toolbelt.customslots;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.IItemHandlerModifiable;

import javax.annotation.Nonnull;

public class ExtensionSlotItemHandler implements IExtensionSlot
{
    protected final IExtensionContainer owner;
    protected final ResourceLocation slotType;
    protected final int slot;
    protected final IItemHandlerModifiable inventory;

    public ExtensionSlotItemHandler(IExtensionContainer owner, ResourceLocation slotType, IItemHandlerModifiable inventory, int slot)
    {
        this.owner = owner;
        this.slotType = slotType;
        this.slot = slot;
        this.inventory = inventory;
    }

    @Nonnull
    @Override
    public IExtensionContainer getContainer()
    {
        return owner;
    }

    @Nonnull
    @Override
    public ResourceLocation getType()
    {
        return slotType;
    }

    /**
     * @return The contents of the slot. The stack is *NOT* required to be of an IExtensionSlotItem!
     */
    @Nonnull
    @Override
    public ItemStack getContents()
    {
        return inventory.getStackInSlot(slot);
    }

    @Override
    public void setContents(@Nonnull ItemStack stack)
    {
        ItemStack oldStack = getContents();
        if (oldStack == stack) return;
        if (!oldStack.isEmpty())
            notifyUnequip(oldStack);
        inventory.setStackInSlot(slot, stack);
        if (!stack.isEmpty())
            notifyEquip(stack);
    }

    @Override
    public void onContentsChanged()
    {
        owner.onContentsChanged(this);
    }

    private void notifyEquip(ItemStack stack)
    {
        stack.getCapability(ExtensionSlotItemCapability.INSTANCE, null).ifPresent((extItem) -> {
            extItem.onEquipped(stack, this);
        });
    }

    private void notifyUnequip(ItemStack stack)
    {
        stack.getCapability(ExtensionSlotItemCapability.INSTANCE, null).ifPresent((extItem) -> {
            extItem.onUnequipped(stack, this);
        });
    }

    public void onWornTick()
    {
        ItemStack stack = getContents();
        if (stack.isEmpty())
            return;
        stack.getCapability(ExtensionSlotItemCapability.INSTANCE, null).ifPresent((extItem) -> {
            extItem.onWornTick(stack, this);
        });
    }
}

package dev.gigaherz.toolbelt.integration;

import dev.gigaherz.sewingkit.api.SewingRecipe;
import dev.gigaherz.toolbelt.belt.ToolBeltItem;
import net.minecraft.core.NonNullList;
import net.minecraft.core.RegistryAccess;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.Container;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.Ingredient;

import javax.annotation.Nullable;

public class SewingUpgradeRecipe extends SewingRecipe
{
    public SewingUpgradeRecipe(ResourceLocation id, String group, NonNullList<Material> materials, @Nullable Ingredient pattern, @Nullable Ingredient tool, ItemStack output)
    {
        super(id, group, materials, pattern, tool, output);
    }

    @Override
    public ItemStack assemble(Container inv, RegistryAccess registryAccess)
    {
        ItemStack inputBelt = ItemStack.EMPTY;
        for (int i = 2; i < 6; i++)
        {
            if (inv.getItem(i).getItem() instanceof ToolBeltItem)
            {
                inputBelt = inv.getItem(i);
                break;
            }
        }
        ItemStack upgradedBelt = super.assemble(inv, registryAccess);
        if (inputBelt.getCount() > 0)
        {
            CompoundTag inputTag = inputBelt.getTag();
            if (inputTag != null)
            {
                CompoundTag tag = upgradedBelt.getOrCreateTag();
                upgradedBelt.setTag(inputTag.copy().merge(tag));
            }
        }
        return upgradedBelt;
    }

    public static class Serializer extends SewingRecipe.Serializer
    {
        @Override
        protected SewingRecipe createRecipe(ResourceLocation recipeId, String group, NonNullList<Material> materials, Ingredient pattern, Ingredient tool, ItemStack result)
        {
            return new SewingUpgradeRecipe(recipeId, group, materials, pattern, tool, result);
        }
    }
}

package dev.gigaherz.toolbelt.network;

import dev.gigaherz.toolbelt.BeltFinder;
import dev.gigaherz.toolbelt.ConfigData;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.items.IItemHandlerModifiable;
import net.minecraftforge.items.ItemHandlerHelper;
import net.minecraftforge.network.NetworkEvent;

import java.util.function.Supplier;

public class SwapItems
{
    public int swapWith;

    public SwapItems(int windowId)
    {
        this.swapWith = windowId;
    }

    public SwapItems(FriendlyByteBuf buf)
    {
        swapWith = buf.readInt();
    }

    public void encode(FriendlyByteBuf buf)
    {
        buf.writeInt(swapWith);
    }

    public boolean handle(Supplier<NetworkEvent.Context> context)
    {
        context.get().enqueueWork(() -> swapItem(swapWith, context.get().getSender()));
        return true;
    }

    public static void swapItem(int swapWith, Player player)
    {
        BeltFinder.findBelt(player).ifPresent((getter) -> {
            ItemStack stack = getter.getBelt();
            if (stack.getCount() <= 0)
                return;

            ItemStack inHand = player.getMainHandItem();

            if (!ConfigData.isItemStackAllowed(inHand))
                return;

            IItemHandlerModifiable cap = (IItemHandlerModifiable) (
                    stack.getCapability(ForgeCapabilities.ITEM_HANDLER, null)
                            .orElseThrow(() -> new RuntimeException("No inventory!")));
            if (swapWith < 0)
            {
                player.setItemInHand(InteractionHand.MAIN_HAND, ItemHandlerHelper.insertItem(cap, inHand, false));
            }
            else
            {
                ItemStack inSlot = cap.getStackInSlot(swapWith);
                player.setItemInHand(InteractionHand.MAIN_HAND, inSlot);
                cap.setStackInSlot(swapWith, inHand);
            }
            getter.syncToClients();
        });
    }
}

package dev.gigaherz.toolbelt.slot;

import com.google.common.collect.ImmutableList;
import dev.gigaherz.toolbelt.ConfigData;
import dev.gigaherz.toolbelt.ToolBelt;
import dev.gigaherz.toolbelt.customslots.ExtensionSlotItemHandler;
import dev.gigaherz.toolbelt.customslots.IExtensionContainer;
import dev.gigaherz.toolbelt.customslots.IExtensionSlot;
import dev.gigaherz.toolbelt.network.SyncBeltSlotContents;
import net.minecraft.core.Direction;
import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.Unit;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.decoration.ArmorStand;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.enchantment.EnchantmentHelper;
import net.minecraft.world.level.GameRules;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityManager;
import net.minecraftforge.common.capabilities.CapabilityToken;
import net.minecraftforge.common.capabilities.ICapabilitySerializable;
import net.minecraftforge.common.util.INBTSerializable;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.living.LivingDropsEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.loading.FMLEnvironment;
import net.minecraftforge.items.ItemHandlerHelper;
import net.minecraftforge.items.ItemStackHandler;
import net.minecraftforge.network.NetworkDirection;
import net.minecraftforge.network.PacketDistributor;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import java.util.Collection;
import java.util.List;

public class BeltExtensionSlot implements IExtensionContainer, INBTSerializable<CompoundTag>
{
    private static final Logger LOGGER = LogManager.getLogger();
    private static final boolean ENABLE_DEBUG_LOGGING = "true".equals(System.getProperty("toolbelt.debug", FMLEnvironment.production ? "false" : "true"));

    private static void printDebugLog(String message, Object... params)
    {
        if (ENABLE_DEBUG_LOGGING)
        {
            LOGGER.info(message, params);
        }
    }

    ////////////////////////////////////////////////////////////
    // Capability support code
    //
    private static final ResourceLocation CAPABILITY_ID = new ResourceLocation("toolbelt", "belt_slot");

    public static Capability<BeltExtensionSlot> CAPABILITY
            = CapabilityManager.get(new CapabilityToken<>()
    {
    });

    public static void register()
    {
        MinecraftForge.EVENT_BUS.register(new AttachHandlers());
        MinecraftForge.EVENT_BUS.register(new EventHandlers());
    }

    public static LazyOptional<BeltExtensionSlot> get(LivingEntity player)
    {
        return player.getCapability(CAPABILITY);
    }

    static class AttachHandlers
    {
        @SubscribeEvent
        public void attachCapabilities(AttachCapabilitiesEvent<Entity> event)
        {
            final Entity entity = event.getObject();
            if (entity instanceof Player || entity instanceof ArmorStand)
            {
                event.addCapability(CAPABILITY_ID, new ICapabilitySerializable<CompoundTag>()
                {
                    final BeltExtensionSlot extensionContainer = new BeltExtensionSlot((LivingEntity) entity)
                    {
                        @Override
                        public void onContentsChanged(IExtensionSlot slot)
                        {
                            if (!ConfigData.customBeltSlotEnabled)
                                return;
                            if (!getOwner().level().isClientSide)
                                syncTo(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(this::getOwner));
                        }
                    };

                    final LazyOptional<BeltExtensionSlot> extensionContainerSupplier = LazyOptional.of(() -> extensionContainer);

                    @Override
                    public CompoundTag serializeNBT()
                    {
                        printDebugLog("Saving belt slot data for player {}({})", entity.getScoreboardName(), entity.getUUID());
                        return extensionContainer.serializeNBT();
                    }

                    @Override
                    public void deserializeNBT(CompoundTag nbt)
                    {
                        extensionContainer.deserializeNBT(nbt);
                        printDebugLog("Read belt slot data for player {}({})", entity.getScoreboardName(), entity.getUUID());
                    }

                    @Override
                    public <T> LazyOptional<T> getCapability(@Nonnull Capability<T> capability, @Nullable Direction facing)
                    {
                        if (CAPABILITY == capability)
                            return extensionContainerSupplier.cast();

                        return LazyOptional.empty();
                    }
                });
            }
        }
    }

    private static class EventHandlers
    {
        @SubscribeEvent
        public void joinWorld(PlayerEvent.PlayerLoggedInEvent event)
        {
            if (!ConfigData.customBeltSlotEnabled)
                return;
            Player target = event.getEntity();
            if (target.level().isClientSide)
                return;
            get(target).ifPresent(BeltExtensionSlot::syncToSelf);
        }

        @SubscribeEvent
        public void joinWorld(PlayerEvent.PlayerChangedDimensionEvent event)
        {
            if (!ConfigData.customBeltSlotEnabled)
                return;
            Player target = event.getEntity();
            if (target.level().isClientSide)
                return;
            get(target).ifPresent(BeltExtensionSlot::syncToSelf);
        }

        @SubscribeEvent
        public void track(PlayerEvent.StartTracking event)
        {
            if (!ConfigData.customBeltSlotEnabled)
                return;
            Entity target = event.getTarget();
            if (target.level().isClientSide)
                return;
            if (target instanceof Player)
            {
                get((LivingEntity) target).ifPresent(BeltExtensionSlot::syncToSelf);
            }
        }

        @SubscribeEvent
        public void entityTick(TickEvent.PlayerTickEvent event)
        {
            if (event.phase != TickEvent.Phase.END)
                return;

            if (ConfigData.customBeltSlotEnabled)
                get(event.player).ifPresent(BeltExtensionSlot::tickAllSlots);
            else
                get(event.player).ifPresent(BeltExtensionSlot::dropContents);
        }

        @SubscribeEvent
        public void playerDeath(LivingDropsEvent event)
        {
            if (!ConfigData.customBeltSlotEnabled)
                return;
            LivingEntity entity = event.getEntity();

            get(entity).ifPresent((instance) -> {
                printDebugLog("Processing belt slot data for entity death {}({})", entity.getScoreboardName(), entity.getUUID());
                IExtensionSlot belt = instance.getBelt();
                ItemStack stack = belt.getContents();
                if (EnchantmentHelper.hasVanishingCurse(stack))
                {
                    stack = ItemStack.EMPTY;
                    belt.setContents(stack);
                }
                if (stack.getCount() > 0)
                {
                    if (entity instanceof Player player)
                    {
                        if (!entity.level().getGameRules().getBoolean(GameRules.RULE_KEEPINVENTORY) && !player.isSpectator())
                        {
                            printDebugLog("Entity is player, and keepInventory is not set. Spilling...");
                            Collection<ItemEntity> old = entity.captureDrops(event.getDrops());
                            player.drop(stack, true, false);
                            entity.captureDrops(old);
                            belt.setContents(ItemStack.EMPTY);
                        }
                    }
                    else
                    {
                        entity.spawnAtLocation(stack);
                        belt.setContents(ItemStack.EMPTY);
                    }
                }
            });
        }

        @SubscribeEvent
        public void playerClone(PlayerEvent.Clone event)
        {
            if (!ConfigData.customBeltSlotEnabled)
                return;
            Player oldPlayer = event.getOriginal();

            // FIXME: workaround for a forge issue that seems to be reappearing too often
            // at this time it's only needed when returning from the end alive
            oldPlayer.revive();

            Player newPlayer = event.getEntity();

            printDebugLog("Processing respawn for entity {}({})", newPlayer.getScoreboardName(), newPlayer.getUUID());
            get(oldPlayer).ifPresent((oldBelt) -> {
                printDebugLog("Old entity has data, copying...");
                ItemStack stack = oldBelt.getBelt().getContents();
                get(newPlayer).map(newBelt -> {
                    LOGGER.warn("New entity has data, contents assigned.");
                    // Transfer any remaining item. If it was death and keepInventory was off,
                    // it will have been removed in LivingDropsEvent.
                    newBelt.getBelt().setContents(stack);
                    return Unit.INSTANCE;
                }).orElseGet(() -> {
                    if (stack.getCount() > 0)
                    {
                        LOGGER.warn("New entity doesn't have capability attached, dropping item to the ground!");
                        oldPlayer.drop(stack, true, false);
                    }
                    return Unit.INSTANCE;
                });
            });
        }
    }

    private void dropContents()
    {
        for (IExtensionSlot slot : slots)
        {
            ItemStack stack = slot.getContents();
            if (stack.getCount() > 0)
            {
                printDebugLog("Player {}({}) has item in the belt slot, but the belt is disabled. Dropping to the ground.", owner.getScoreboardName(), owner.getUUID());
                if (owner instanceof Player)
                    ItemHandlerHelper.giveItemToPlayer((Player) owner, stack);
                else
                    owner.spawnAtLocation(stack, 0.1f);
                slot.setContents(ItemStack.EMPTY);
            }
        }
    }

    private void syncToSelf()
    {
        syncTo((Player) owner);
    }

    protected void syncTo(Player target)
    {
        SyncBeltSlotContents message = new SyncBeltSlotContents((Player) owner, this);
        ToolBelt.channel.sendTo(message, ((ServerPlayer) target).connection.connection, NetworkDirection.PLAY_TO_CLIENT);
    }

    protected void syncTo(PacketDistributor.PacketTarget target)
    {
        SyncBeltSlotContents message = new SyncBeltSlotContents((Player) owner, this);
        ToolBelt.channel.send(target, message);
    }

    ////////////////////////////////////////////////////////////
    // Equipment container implementation
    //
    public static final ResourceLocation BELT = new ResourceLocation("examplemod", "belt");

    private final LivingEntity owner;
    private final ItemStackHandler inventory = new ItemStackHandler(1)
    {
        @Override
        protected void onContentsChanged(int slot)
        {
            super.onContentsChanged(slot);
            belt.onContentsChanged();
        }
    };
    private final ExtensionSlotItemHandler belt = new ExtensionSlotItemHandler(this, BELT, inventory, 0);
    private final ImmutableList<IExtensionSlot> slots = ImmutableList.of(belt);

    private BeltExtensionSlot(LivingEntity owner)
    {
        this.owner = owner;
    }

    @Nonnull
    @Override
    public LivingEntity getOwner()
    {
        return owner;
    }

    @Nonnull
    @Override
    public ImmutableList<IExtensionSlot> getSlots()
    {
        return slots;
    }

    @Override
    public void onContentsChanged(IExtensionSlot slot)
    {

    }

    @Nonnull
    public IExtensionSlot getBelt()
    {
        return belt;
    }

    private void tickAllSlots()
    {
        for (IExtensionSlot slot : slots)
        {
            ((ExtensionSlotItemHandler) slot).onWornTick();
        }
    }

    public void setAll(NonNullList<ItemStack> stacks)
    {
        List<IExtensionSlot> slots = getSlots();
        for (int i = 0; i < slots.size(); i++)
        {
            slots.get(i).setContents(stacks.get(i));
        }
    }

    @Override
    public CompoundTag serializeNBT()
    {
        return inventory.serializeNBT();
    }

    @Override
    public void deserializeNBT(CompoundTag nbt)
    {
        inventory.deserializeNBT(nbt);
    }
}
